import{_ as s,C as i,c as l,o as d,a3 as n,G as a,j as e,a as r}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Work Orders","description":"","frontmatter":{},"headers":[],"relativePath":"master/manufacturing/operations/work-orders.md","filePath":"master/manufacturing/operations/work-orders.md","lastUpdated":1791532126000}'),g={name:"master/manufacturing/operations/work-orders.md"};function u(m,t,h,p,c,k){const o=i("ImagePopup");return d(),l("div",null,[t[4]||(t[4]=n('<h1 id="work-orders" tabindex="-1">Work Orders <a class="header-anchor" href="#work-orders" aria-label="Permalink to &quot;Work Orders&quot;">​</a></h1><p>A <strong>Work Order (WO)</strong> represents a <strong>single operation</strong> of a manufacturing order executed at a specific <strong>Work Center</strong>.<br> Work orders give shop-floor operators a focused view of what needs to be done, with worksheets, time tracking, and component checklists.</p><p><strong>Use Case:</strong><br> Use Work Orders to schedule, dispatch, and track every production step in real time. They are essential for businesses that produce items in multiple stages (cutting → assembly → painting → packaging) and want operator-level visibility.</p><blockquote><p><strong>In simple words:</strong> If a <a href="./manufacturing-orders.html">Manufacturing Order</a> says <em>&quot;build 10 chairs&quot;</em>, the Work Orders are the individual to-do items for the floor: <em>&quot;cut the wood&quot;, &quot;assemble the frame&quot;, &quot;polish the surface&quot;</em> — each handled at its own station.</p></blockquote><blockquote><p>Work Orders are available only when <strong>Work Orders</strong> is enabled in <a href="./../settings.html">Manufacturing Settings</a>. Sequencing requires <strong>Work Order Dependencies</strong> to also be enabled. Each work order runs an <a href="./../configurations/operations.html">Operation</a> at a <a href="./../configurations/work-centers.html">Work Center</a>.</p></blockquote><h2 id="how-work-orders-are-created" tabindex="-1">How Work Orders Are Created <a class="header-anchor" href="#how-work-orders-are-created" aria-label="Permalink to &quot;How Work Orders Are Created&quot;">​</a></h2><p>Work orders are <strong>generated automatically — there is no manual creation step</strong>. When you confirm a <a href="./manufacturing-orders.html">Manufacturing Order</a> whose <a href="./../products/bills-of-material.html">Bill of Material</a> has <a href="./../configurations/operations.html">Operations</a> defined, the system creates <strong>one work order for each operation</strong>.</p><p>To open them, navigate to <strong><code>Manufacturing → Operations → Work Orders</code></strong> as shown below:</p>',8)),a(o,{src:"/images1/manufacturing/wo_navigation.png",alt:"Work Orders Navigation"}),t[5]||(t[5]=n('<h2 id="work-order-list-—-start-stop-finish" tabindex="-1">Work Order List — Start, Stop &amp; Finish <a class="header-anchor" href="#work-order-list-—-start-stop-finish" aria-label="Permalink to &quot;Work Order List — Start, Stop &amp; Finish&quot;">​</a></h2><p>The <strong>Work Orders</strong> list shows <strong>every operation across all manufacturing orders</strong> in one place, so operators always know what to run next. Each row displays: <strong>Operation</strong>, <strong>Work Center</strong>, <strong>Manufacturing Order</strong>, <strong>Product</strong>, <strong>Quantity Remaining</strong>, <strong>Lot/Serial</strong>, <strong>Start</strong>, <strong>End</strong>, <strong>Expected Duration</strong>, <strong>Real Duration</strong>, and <strong>Status</strong>.</p><p>Each row carries inline controls to run the operation directly from the list:</p><ul><li><strong>Start</strong> — begins the operation and starts a <strong>live timer</strong>. The <strong>Real Duration</strong> counts up in real time and the status changes to <strong>In Progress</strong>.</li><li><strong>Stop</strong> — pauses the timer (for a break, setup, or quality stop). The elapsed interval is saved to the <strong>Time Tracking</strong> tab; press <strong>Start</strong> again to resume.</li><li><strong>Finish</strong> — marks the operation complete once the work is done. The status changes to <strong>Finished</strong> and the next work order in the sequence is unblocked.</li></ul>',4)),a(o,{src:"/images1/manufacturing/wo_list_view.png",alt:"Work Order List View"}),t[6]||(t[6]=n('<p>You can also:</p><ul><li><strong>Group by:</strong> Status, Work Center, Manufacturing Order, Product, Start, or End.</li><li><strong>Filter by:</strong> Work Order, Status, Operation, Work Center, Manufacturing Order, Product, Start/End date, Created at, or Updated at.</li></ul><blockquote><p>The <strong>Real Duration</strong> is calculated automatically from every Start/Stop interval — operators never type it in by hand.</p></blockquote><h2 id="work-order-stages" tabindex="-1">Work Order Stages <a class="header-anchor" href="#work-order-stages" aria-label="Permalink to &quot;Work Order Stages&quot;">​</a></h2><p>A work order moves through the following stages:</p><p><code>Waiting for another Work Order</code> → <code>Waiting for Components</code> → <code>Ready</code> → <code>In Progress</code> → <code>Finished</code></p><table tabindex="0"><thead><tr><th>Stage</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Waiting for another Work Order</strong></td><td>A predecessor operation (listed in the <strong>Blocked By</strong> tab) has not finished yet.</td></tr><tr><td><strong>Waiting for Components</strong></td><td>The components needed for this step are not yet available in stock.</td></tr><tr><td><strong>Ready</strong></td><td>All dependencies and components are satisfied — the operation can be started.</td></tr><tr><td><strong>In Progress</strong></td><td>An operator has clicked <strong>Start</strong>; the timer is running.</td></tr><tr><td><strong>Finished</strong></td><td>The operation is complete.</td></tr></tbody></table><h2 id="work-order-view-page" tabindex="-1">Work Order View Page <a class="header-anchor" href="#work-order-view-page" aria-label="Permalink to &quot;Work Order View Page&quot;">​</a></h2><p>Click <strong>View</strong> on any row to open the <strong>Work Order View Page</strong>, where you can run the operation and see its full detail.</p>',9)),a(o,{src:"/images1/manufacturing/wo_view_page.png",alt:"Work Order View Page"}),t[7]||(t[7]=n("<p>The general section shows the key details of the operation:</p><ul><li><strong><em>Work Order:</em></strong> Name/title of the operation (e.g. <em>Assembly</em>).</li><li><strong><em>Work Center:</em></strong> Station where the operation runs.</li><li><strong><em>Product:</em></strong> Product being produced or processed at this step.</li><li><strong><em>Quantity:</em></strong> Quantity that must be processed at this work center.</li><li><strong><em>Manufacturing Order:</em></strong> Parent MO this work order belongs to.</li><li><strong><em>Lot/Serial Number:</em></strong> Lot or serial assigned to the produced unit (used when the product is tracked).</li><li><strong><em>Start Date / End Date:</em></strong> Scheduled time window (<code>Start to End</code>).</li><li><strong><em>Expected Duration:</em></strong> Planned duration in minutes.</li><li><strong><em>Real Duration:</em></strong> Actual time logged via the Start/Stop timer (read-only).</li></ul>",2)),a(o,{src:"/images1/manufacturing/wo_general_section.png",alt:"Work Order General Section"}),t[8]||(t[8]=n('<p>The view page also exposes the same <strong>Start</strong>, <strong>Stop</strong>, and <strong>Finish</strong> controls as the list, plus the following tabs.</p><h3 id="time-tracking-tab" tabindex="-1">Time Tracking Tab <a class="header-anchor" href="#time-tracking-tab" aria-label="Permalink to &quot;Time Tracking Tab&quot;">​</a></h3><p>Records every time block logged against this work order. Multiple operators can contribute, and every Start/Stop interval is appended here automatically.</p><ul><li><strong><em>User:</em></strong> Operator performing the work.</li><li><strong><em>Duration:</em></strong> Time spent (auto-computed from start/end).</li><li><strong><em>Start Date / End Date:</em></strong> Time window of the block.</li><li><strong><em>Productivity:</em></strong> Productivity reason (e.g. <em>Production</em>, <em>Setup</em>, <em>Break</em>, <em>Quality Control</em>) — used in OEE reports.</li></ul><p>A footer total displays the cumulative <strong>Real Duration</strong>.</p>',5)),a(o,{src:"/images1/manufacturing/wo_time_tracking_tab.png",alt:"Work Order Time Tracking Tab"}),t[9]||(t[9]=n('<h3 id="components-tab" tabindex="-1">Components Tab <a class="header-anchor" href="#components-tab" aria-label="Permalink to &quot;Components Tab&quot;">​</a></h3><p>Shows the components consumed at this work order — auto-populated from the BoM (linked through <em>Consumed in Operation</em>).</p><ul><li><strong><em>Product:</em></strong> The component.</li><li><strong><em>To Consume:</em></strong> Planned quantity.</li><li><strong><em>Quantity:</em></strong> Actual consumed quantity (filled in during production).</li><li><strong><em>UoM:</em></strong> Unit of measure.</li></ul><h3 id="work-instruction-tab" tabindex="-1">Work Instruction Tab <a class="header-anchor" href="#work-instruction-tab" aria-label="Permalink to &quot;Work Instruction Tab&quot;">​</a></h3><p>Displays the operator instructions configured on the operation.</p><ul><li><strong><em>Operation:</em></strong> Linked operation name.</li><li><strong><em>Worksheet:</em></strong> Embedded PDF, Google Slide, or text description that operators follow to complete the work.</li></ul>',6)),a(o,{src:"/images1/manufacturing/wo_work_instruction_tab.png",alt:"Work Instruction Tab"}),t[10]||(t[10]=n('<h3 id="blocked-by-tab" tabindex="-1">Blocked By Tab <a class="header-anchor" href="#blocked-by-tab" aria-label="Permalink to &quot;Blocked By Tab&quot;">​</a></h3><p>Visible when <strong>Work Order Dependencies</strong> is enabled. Lists every work order that must finish before this one becomes <strong>Ready</strong> — while any predecessor is unfinished, this work order stays in the <strong>Waiting for another Work Order</strong> stage.</p><ul><li><strong><em>Work Order:</em></strong> Predecessor work order.</li><li><strong><em>Work Center:</em></strong> Work center of the predecessor.</li><li><strong><em>Status:</em></strong> Current status of the predecessor — when all show <strong>Finished</strong>, this work order becomes available.</li></ul><h2 id="running-a-work-order" tabindex="-1">Running a Work Order <a class="header-anchor" href="#running-a-work-order" aria-label="Permalink to &quot;Running a Work Order&quot;">​</a></h2>',4)),e("ol",null,[t[2]||(t[2]=e("li",null,[e("p",null,[r("From the "),e("strong",null,"Work Orders"),r(" list (or the view page), find an operation in the "),e("strong",null,"Ready"),r(" stage.")])],-1)),e("li",null,[t[0]||(t[0]=e("p",null,[r("Click "),e("strong",null,"Start"),r(" to begin — the timer runs and the status becomes "),e("strong",null,"In Progress"),r(".")],-1)),a(o,{src:"/images1/manufacturing/wo_list_view.png",alt:"Work Order List View"})]),t[3]||(t[3]=e("li",null,[e("p",null,[r("Click "),e("strong",null,"Stop"),r(" to pause for a break or quality stop; click "),e("strong",null,"Start"),r(" again to resume. Every interval is saved to the "),e("strong",null,"Time Tracking"),r(" tab.")])],-1)),e("li",null,[t[1]||(t[1]=e("p",null,[r("When the work is complete, click "),e("strong",null,"Finish"),r(". The status becomes "),e("strong",null,"Finished"),r(" and the next work order in the sequence is unblocked.")],-1)),a(o,{src:"/images1/manufacturing/wo_done_action.png",alt:"Finish Work Order"})])]),t[11]||(t[11]=n('<h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>Work Orders bring your manufacturing plan to life on the shop floor:</p><ul><li>They are created automatically when a <a href="./manufacturing-orders.html">Manufacturing Order</a> is confirmed — one per operation.</li><li>Operators run them straight from the list with <strong>Start / Stop / Finish</strong> controls.</li><li>Real-time <strong>time tracking</strong> feeds productivity and OEE reports.</li><li><strong>Dependencies</strong> keep <a href="./../configurations/operations.html">Operations</a> in the correct sequence automatically.</li><li>Component consumption is recorded at the exact step where it happens, giving you accurate cost and traceability data.</li></ul><blockquote><p><strong>Related:</strong> Work Orders are generated and driven by the <a href="./manufacturing-orders.html">Manufacturing Order</a>. To change a step&#39;s default duration or worksheet, edit its <a href="./../configurations/operations.html">Operation</a>.</p></blockquote>',4))])}const w=s(g,[["render",u]]);export{b as __pageData,w as default};
